// Build the ring here. The tests read head_ and tail_ by these names.
template <std::size_t N>
class TickRing {
public:
    bool try_push(long long v) { (void)v; return false; }
    bool try_pop(long long& out) { (void)out; return false; }
    int drain(std::vector<long long>& out, int max) { (void)out; (void)max; return 0; }
    int size() const { return 0; }
    std::atomic<unsigned> head_{0};
    std::atomic<unsigned> tail_{0};
};

widget.solution:
#include <array>
#include <atomic>
#include <cstddef>
#include <vector>

template <std::size_t N>
class TickRing {
    static_assert(N > 0 && (N & (N - 1)) == 0, "N must be a power of two");
public:
    bool try_push(long long v) {
        unsigned t = tail_.load(std::memory_order_relaxed);   // only the producer writes tail_
        unsigned h = head_.load(std::memory_order_acquire);   // see the consumer's frees
        if (t - h == N) return false;                         // full; unsigned difference survives the wrap
        buf_[t & (N - 1)] = v;
        tail_.store(t + 1, std::memory_order_release);        // publish the slot
        return true;
    }
    bool try_pop(long long& out) {
        unsigned h = head_.load(std::memory_order_relaxed);   // only the consumer writes head_
        unsigned t = tail_.load(std::memory_order_acquire);   // see the producer's writes
        if (h == t) return false;                             // empty: out unchanged
        out = buf_[h & (N - 1)];
        head_.store(h + 1, std::memory_order_release);        // free the slot
        return true;
    }
    int drain(std::vector<long long>& out, int max) {
        unsigned h = head_.load(std::memory_order_relaxed);
        unsigned t = tail_.load(std::memory_order_acquire);   // one acquire for the batch
        unsigned n = t - h;
        if (max < 0) max = 0;
        if (n > static_cast<unsigned>(max)) n = static_cast<unsigned>(max);
        for (unsigned i = 0; i < n; ++i) out.push_back(buf_[(h + i) & (N - 1)]);
        head_.store(h + n, std::memory_order_release);        // one release frees them all
        return static_cast<int>(n);
    }
    int size() const {
        return static_cast<int>(tail_.load(std::memory_order_acquire) - head_.load(std::memory_order_acquire));
    }
    alignas(64) std::atomic<unsigned> head_{0};
    alignas(64) std::atomic<unsigned> tail_{0};
private:
    alignas(64) std::array<long long, N> buf_{};
};
